document.getElementById('f').addEventListener('submit', (e) => {
  e.preventDefault()
  const data = new FormData(e.target)
  const ok = data.get('email') === 'demo@example.test' && data.get('password') === 'correct-horse'
  if (ok) document.querySelector('main').innerHTML = '<h1>Dashboard</h1>'
  else document.getElementById('msg').textContent = 'Wrong email or password'
})

